// 5. Control de HUD nativo a nivel Snippet
function setHotbarSnippet(visible) {
  estadoHotbar = !!visible;
  if (visible) {
    document.body.classList.remove('mc-intro');
  } else {
    document.body.classList.add('mc-intro');
  }
}

// 6. Mandos del Director y Cámara Cinemática Orbital con Encuadre Sagrado
let cineRAF = null;
let cineActivo = false;
let estadoVolarPrev = false;
let estadoFantasmaPrev = false;

// El centro del santuario y el punto focal de la mirada (mitad-alta de la pagoda en y=26)
const centroEscena = [48, 26, 52];

function calcularAlturaIdeal(dist) {
  // Elevación proporcional para abarcar desde el lecho del lago (y=10) hasta el pináculo de oro (y=44)
  return 18 + (dist * 0.32);
}

alturaObjetivo = calcularAlturaIdeal(radioObjetivo);
alturaOrbita = alturaObjetivo;

function iniciarCamaraOrbital() {
  if (cineActivo) return;
  cineActivo = true;
  estadoVolarPrev = !!(mc.volar);
  estadoFantasmaPrev = !!(mc.fantasma);
  game.volar(true);
  game.fantasma(true);

  // En modo orbital ocultamos la hotbar con mc-intro
  setHotbarSnippet(false);
  game.showTool(false);

  const t0 = performance.now();

  function paso() {
    if (!cineActivo) return;

    // Transición suave (amortiguación exponencial lerp) de radio y altura
    radioOrbita += (radioObjetivo - radioOrbita) * 0.05;
    alturaOrbita += (alturaObjetivo - alturaOrbita) * 0.05;

    const t = (performance.now() - t0) * 0.00013;
    mc.pos[0] = centroEscena[0] + Math.cos(t) * radioOrbita;
    mc.pos[1] = alturaOrbita + Math.sin(t * 0.5) * (radioOrbita * 0.04);
    mc.pos[2] = centroEscena[2] + Math.sin(t) * radioOrbita;
    mc.vel = [0, 0, 0];

    // Orientación exacta hacia el corazón de la pagoda (centroEscena en x=48, y=26, z=52)
    const dx = centroEscena[0] - mc.pos[0];
    const dy = centroEscena[1] - mc.pos[1];
    const dz = centroEscena[2] - mc.pos[2];
    const distPlano = Math.hypot(dx, dz);

    mc.yaw = Math.atan2(-dx, -dz);
    mc.pitch = Math.atan2(dy, distPlano); // Ángulo exacto de apuntado hacia la pagoda

    cineRAF = requestAnimationFrame(paso);
  }
  paso();
}

function detenerCamaraOrbital() {
  if (!cineActivo) return;
  cineActivo = false;
  if (cineRAF) cancelAnimationFrame(cineRAF);
  game.fantasma(estadoFantasmaPrev);
  game.volar(estadoVolarPrev);

  // Al salir del modo orbital a jugar libremente, MOSTRAR la hotbar y herramienta
  setHotbarSnippet(true);
  game.showTool(true);

  toast("🎮 Modo juego: Hotbar y control libre restaurados");
}

function toggleCamaraOrbital() {
  if (cineActivo) detenerCamaraOrbital();
  else {
    toast("🎥 Cámara cinemática orbital (WASD para cancelar)");
    iniciarCamaraOrbital();
  }
}

// Al pulsar W, A, S, D o Espacio salimos de la órbita y mostramos la hotbar para jugar
window.addEventListener('keydown', (e) => {
  if (['w', 'a', 's', 'd', ' '].includes(e.key.toLowerCase()) && cineActivo) {
    detenerCamaraOrbital();
  }
}, { capture: true });

