function refrescarEntorno() {
  if (estadoNiebla) {
    game.entorno('NIEBLA', 1.5);
  } else if (estadoNoche) {
    aplicarAtmosfera(ATMOSFERA.NOCHE_LUMINOSA, 1.5);
  } else {
    aplicarAtmosfera(ATMOSFERA.ATARDECER, 1.5);
  }
}

function engancharSliderOrbita() {
  const slider = document.getElementById('slider-dist-orbita');
  const lbl = document.getElementById('lbl-dist-orbita');
  if (slider) {
    slider.addEventListener('input', (e) => {
      const val = parseFloat(e.target.value) || 50;
      radioObjetivo = val;
      alturaObjetivo = calcularAlturaIdeal(val);
      if (lbl) lbl.textContent = Math.round(val) + 'm';
    });
  }
}

function registrarMenuOSD() {
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', hud: true, showTool: true, html: htmlOSD() });
}

function abrirMenuOSD() {
  registrarMenuOSD();
  game.osd.abrir('menu_santuario');
  engancharSliderOrbita();
}

function actualizarMenuOSD() {
  if (game.osd.abierta) {
    game.osd.html(htmlOSD());
    engancharSliderOrbita();
  }
}

registrarMenuOSD();

